import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';
import { useLanguage } from '../context/LanguageContext';

const AdminDashboard = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const { t } = useLanguage();
    const [user, setUser] = useState(null);
    const [appointments, setAppointments] = useState([]);
    const [clients, setClients] = useState([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState('appointments');

    // Dropdown state
    const [dropdownOpen, setDropdownOpen] = useState(false);
    const dropdownRef = useRef(null);

    // Analytics state
    const [showAnalytics, setShowAnalytics] = useState(false);

    // Close dropdown when clicking outside
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    useEffect(() => {
        // Check if user is admin
        const storedUser = localStorage.getItem('user');
        if (storedUser) {
            const userData = JSON.parse(storedUser);
            if (userData.role !== 'admin') {
                navigate('/services');
                return;
            }
            setUser(userData);
        }

        fetchData();
    }, [navigate]);

    const fetchData = async () => {
        try {
            const token = localStorage.getItem('token');

            // Fetch all appointments
            const appointmentsRes = await axios.get('http://localhost:5000/api/appointments', {
                headers: { Authorization: `Bearer ${token}` }
            });
            const allAppointments = appointmentsRes.data.data || [];
            setAppointments(allAppointments);

            // Extract unique clients from appointments
            const clientMap = new Map();
            allAppointments.forEach(app => {
                if (app.client) {
                    const clientId = app.client._id || app.client;
                    if (!clientMap.has(clientId)) {
                        clientMap.set(clientId, {
                            ...app.client,
                            appointmentCount: 1,
                            appointments: [app]
                        });
                    } else {
                        const existing = clientMap.get(clientId);
                        existing.appointmentCount += 1;
                        existing.appointments.push(app);
                    }
                }
            });
            setClients(Array.from(clientMap.values()));

        } catch (err) {
            console.error("Error fetching admin data:", err);
        } finally {
            setLoading(false);
        }
    };

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        navigate('/admin-login');
    };

    const isActive = (path) => location.pathname === path;

    const formatDate = (dateString) => {
        const date = new Date(dateString);
        return date.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
    };

    const getStatusColor = (status) => {
        switch(status) {
            case 'Pending': return 'yellow';
            case 'Confirmed': return 'green';
            case 'Completed': return 'blue';
            case 'Cancelled': return 'red';
            default: return 'gray';
        }
    };

    // Dropdown options
    const dropdownItems = [
        { label: '📋 List of all appointments', action: () => setActiveTab('appointments') },
        { label: '✅ Appointment Confirmed', action: () => { setActiveTab('confirmed'); } },
        { label: '👥 List of all clients and contact', action: () => setActiveTab('clients') }
    ];

    // Filter appointments for confirmed tab
    const confirmedAppointments = appointments.filter(app => app.status === 'Confirmed');

    // Analytics calculations
    const getAnalytics = () => {
        const today = new Date().toISOString().split('T')[0];
        const totalClients = clients.length;
        const todaysAppointments = appointments.filter(app => {
            const appDate = new Date(app.appointmentDate).toISOString().split('T')[0];
            return appDate === today;
        }).length;
        const upcomingAppointments = appointments.filter(app => {
            const appDate = new Date(app.appointmentDate);
            return appDate >= new Date() && app.status !== 'Cancelled' && app.status !== 'Completed';
        }).length;
        const pendingRequests = appointments.filter(app => app.status === 'Pending').length;
        const confirmedCount = appointments.filter(app => app.status === 'Confirmed').length;
        const completedCount = appointments.filter(app => app.status === 'Completed').length;
        const cancelledCount = appointments.filter(app => app.status === 'Cancelled').length;
        const totalRevenue = appointments
            .filter(app => app.status !== 'Cancelled')
            .reduce((sum, app) => sum + (app.price || 0), 0);

        return {
            totalClients,
            todaysAppointments,
            upcomingAppointments,
            pendingRequests,
            confirmedCount,
            completedCount,
            cancelledCount,
            totalRevenue
        };
    };

    return (
        <div className="admin-page">
            {/* NEW NAVBAR DESIGN */}
            <nav className="admin-navbar-new">
                <div className="nav-logo">BeautyBook Admin</div>

                <div className="nav-links-container">
                    {/* Dropdown Button */}
                    <div className="dropdown-container" ref={dropdownRef}>
                        <button 
                            className={`nav-dropdown-btn ${dropdownOpen ? 'active' : ''}`}
                            onClick={() => setDropdownOpen(!dropdownOpen)}
                        >
                            📋 List
                            <span className="dropdown-arrow">▼</span>
                        </button>

                        {dropdownOpen && (
                            <div className="dropdown-menu">
                                {dropdownItems.map((item, index) => (
                                    <div 
                                        key={index} 
                                        className="dropdown-item"
                                        onClick={() => {
                                            item.action();
                                            setDropdownOpen(false);
                                        }}
                                    >
                                        {item.label}
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Settings Button */}
                    <button 
                        className="nav-icon-btn"
                        onClick={() => navigate('/admin/settings')}
                        title="Settings"
                    >
                        ⚙️
                    </button>

                    {/* Analytics Button */}
                    <button 
                        className="nav-icon-btn"
                        onClick={() => setShowAnalytics(!showAnalytics)}
                        title="Analytics"
                    >
                        📊
                    </button>

                    {/* Logout Button */}
                    <button 
                        className="nav-logout-btn"
                        onClick={handleLogout}
                    >
                        🚪 Logout
                    </button>
                </div>
            </nav>

            {/* ANALYTICS MODAL (Floating Chart) */}
            {showAnalytics && (
                <div className="analytics-modal-overlay" onClick={() => setShowAnalytics(false)}>
                    <div className="analytics-modal" onClick={(e) => e.stopPropagation()}>
                        <div className="analytics-header">
                            <h2>📊 Dashboard Analytics</h2>
                            <button className="close-analytics-btn" onClick={() => setShowAnalytics(false)}>✕</button>
                        </div>

                        <div className="analytics-grid">
                            <div className="analytics-card total-clients">
                                <div className="analytics-icon">👥</div>
                                <div className="analytics-info">
                                    <h3>{getAnalytics().totalClients}</h3>
                                    <p>Total Clients</p>
                                </div>
                            </div>

                            <div className="analytics-card today-appointments">
                                <div className="analytics-icon">📅</div>
                                <div className="analytics-info">
                                    <h3>{getAnalytics().todaysAppointments}</h3>
                                    <p>Today's Appointments</p>
                                </div>
                            </div>

                            <div className="analytics-card upcoming">
                                <div className="analytics-icon">⏰</div>
                                <div className="analytics-info">
                                    <h3>{getAnalytics().upcomingAppointments}</h3>
                                    <p>Upcoming Appointments</p>
                                </div>
                            </div>

                            <div className="analytics-card pending">
                                <div className="analytics-icon">⏳</div>
                                <div className="analytics-info">
                                    <h3>{getAnalytics().pendingRequests}</h3>
                                    <p>Pending Requests</p>
                                </div>
                            </div>

                            <div className="analytics-card confirmed">
                                <div className="analytics-icon">✅</div>
                                <div className="analytics-info">
                                    <h3>{getAnalytics().confirmedCount}</h3>
                                    <p>Confirmed Appointments</p>
                                </div>
                            </div>

                            <div className="analytics-card completed">
                                <div className="analytics-icon">🏁</div>
                                <div className="analytics-info">
                                    <h3>{getAnalytics().completedCount}</h3>
                                    <p>Completed Appointments</p>
                                </div>
                            </div>

                            <div className="analytics-card cancelled">
                                <div className="analytics-icon">❌</div>
                                <div className="analytics-info">
                                    <h3>{getAnalytics().cancelledCount}</h3>
                                    <p>Cancelled Appointments</p>
                                </div>
                            </div>

                            <div className="analytics-card revenue">
                                <div className="analytics-icon">💰</div>
                                <div className="analytics-info">
                                    <h3>{getAnalytics().totalRevenue} DA</h3>
                                    <p>Total Revenue</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            <div className="admin-content">
                <h1 className="admin-welcome">Welcome back, {user?.firstName || 'Admin'}! 👋</h1>

                {/* Tabs */}
                <div className="admin-tabs">
                    {activeTab === 'appointments' && (
                        <button className="admin-tab active" onClick={() => setActiveTab('appointments')}>
                            📋 List of all appointments
                        </button>
                    )}
                    {activeTab === 'confirmed' && (
                        <button className="admin-tab active" onClick={() => setActiveTab('confirmed')}>
                            ✅ Appointment Confirmed
                        </button>
                    )}
                    {activeTab === 'clients' && (
                        <button className="admin-tab active" onClick={() => setActiveTab('clients')}>
                            👥 List of all clients
                        </button>
                    )}
                </div>

                {loading ? (
                    <div className="loading-spinner">Loading...</div>
                ) : (
                    <div className="admin-content-body">
                        {/* Appointments Tab */}
                        {activeTab === 'appointments' && (
                            <div className="appointments-list-container">
                                {appointments.length === 0 ? (
                                    <div className="empty-state">
                                        <p>No appointments yet.</p>
                                    </div>
                                ) : (
                                    appointments.map((app) => (
                                        <div key={app._id} className="admin-appointment-card">
                                            <div className="appointment-header">
                                                <h3 className="service-name">{app.service?.name || 'Unknown Service'}</h3>
                                                <span className={`status-badge ${app.status.toLowerCase()}`}>
                                                    {app.status}
                                                </span>
                                            </div>
                                            <div className="appointment-details">
                                                <div className="detail-row">
                                                    <span className="label">Client:</span>
                                                    <span className="value">{app.client?.firstName || 'Unknown'} {app.client?.lastName || ''}</span>
                                                </div>
                                                <div className="detail-row">
                                                    <span className="label">Phone:</span>
                                                    <span className="value">{app.client?.phone || 'N/A'}</span>
                                                </div>
                                                <div className="detail-row">
                                                    <span className="label">Email:</span>
                                                    <span className="value">{app.client?.email || 'N/A'}</span>
                                                </div>
                                                <div className="detail-row">
                                                    <span className="label">Price:</span>
                                                    <span className="value">{app.price} DA</span>
                                                </div>
                                                <div className="detail-row">
                                                    <span className="label">Duration:</span>
                                                    <span className="value">{app.service?.duration || 'N/A'} min</span>
                                                </div>
                                                <div className="detail-row">
                                                    <span className="label">Date:</span>
                                                    <span className="value">{formatDate(app.appointmentDate)}</span>
                                                </div>
                                                <div className="detail-row">
                                                    <span className="label">Time:</span>
                                                    <span className="value">{app.startTime} - {app.endTime}</span>
                                                </div>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        )}

                        {/* Confirmed Appointments Tab */}
                        {activeTab === 'confirmed' && (
                            <div className="appointments-list-container">
                                {confirmedAppointments.length === 0 ? (
                                    <div className="empty-state">
                                        <p>No confirmed appointments yet.</p>
                                    </div>
                                ) : (
                                    confirmedAppointments.map((app) => (
                                        <div key={app._id} className="admin-appointment-card">
                                            <div className="appointment-header">
                                                <h3 className="service-name">{app.service?.name || 'Unknown Service'}</h3>
                                                <span className="status-badge confirmed">✅ Confirmed</span>
                                            </div>
                                            <div className="appointment-details">
                                                <div className="detail-row">
                                                    <span className="label">Client:</span>
                                                    <span className="value">{app.client?.firstName || 'Unknown'} {app.client?.lastName || ''}</span>
                                                </div>
                                                <div className="detail-row">
                                                    <span className="label">Phone:</span>
                                                    <span className="value">{app.client?.phone || 'N/A'}</span>
                                                </div>
                                                <div className="detail-row">
                                                    <span className="label">Email:</span>
                                                    <span className="value">{app.client?.email || 'N/A'}</span>
                                                </div>
                                                <div className="detail-row">
                                                    <span className="label">Price:</span>
                                                    <span className="value">{app.price} DA</span>
                                                </div>
                                                <div className="detail-row">
                                                    <span className="label">Date:</span>
                                                    <span className="value">{formatDate(app.appointmentDate)}</span>
                                                </div>
                                                <div className="detail-row">
                                                    <span className="label">Time:</span>
                                                    <span className="value">{app.startTime} - {app.endTime}</span>
                                                </div>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        )}

                        {/* Clients Tab */}
                        {activeTab === 'clients' && (
                            <div className="clients-list-container">
                                {clients.length === 0 ? (
                                    <div className="empty-state">
                                        <p>No clients yet.</p>
                                    </div>
                                ) : (
                                    clients.map((client) => (
                                        <div key={client._id} className="admin-client-card">
                                            <div className="client-header">
                                                <h3 className="client-name">{client.firstName || 'Unknown'} {client.lastName || ''}</h3>
                                                <span className="appointment-count">📅 {client.appointmentCount} appointments</span>
                                            </div>
                                            <div className="client-details">
                                                <div className="detail-row">
                                                    <span className="label">Phone:</span>
                                                    <span className="value">{client.phone || 'N/A'}</span>
                                                </div>
                                                <div className="detail-row">
                                                    <span className="label">Email:</span>
                                                    <span className="value">{client.email || 'N/A'}</span>
                                                </div>
                                            </div>
                                            {client.appointments && client.appointments.length > 0 && (
                                                <div className="client-appointments">
                                                    <h4>Recent Appointments:</h4>
                                                    {client.appointments.slice(0, 3).map((app, index) => (
                                                        <div key={index} className="client-appointment-item">
                                                            <span>{app.service?.name || 'Unknown'}</span>
                                                            <span>{formatDate(app.appointmentDate)}</span>
                                                            <span className={`status-badge ${app.status.toLowerCase()}`}>
                                                                {app.status}
                                                            </span>
                                                        </div>
                                                    ))}
                                                    {client.appointments.length > 3 && (
                                                        <div className="more-appointments">
                                                            + {client.appointments.length - 3} more appointments
                                                        </div>
                                                    )}
                                                </div>
                                            )}
                                        </div>
                                    ))
                                )}
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
};

export default AdminDashboard;
